package com.hbm.machine.oilextraction;
import com.hbm.multiblock.DummyableBlock;
import com.mojang.serialization.MapCodec;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.SoundType;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.MapColor;
import net.minecraft.world.level.storage.loot.LootParams;
import net.minecraft.world.level.storage.loot.parameters.LootContextParams;
/** Source occupied cuboid union, true persistent harvesting, real derrick fuel explosion. */
public final class OilDrillBlock extends DummyableBlock {
 public final OilDrillKind kind;public OilDrillBlock(OilDrillKind kind){super(Properties.of().mapColor(MapColor.METAL).strength(5,20).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());this.kind=kind;}
 @Override protected MapCodec<? extends DummyableBlock> codec(){return simpleCodec(ignored->new OilDrillBlock(kind));}@Override public int[] dimensions(){return kind==OilDrillKind.WELL?new int[]{9,0,1,1,1,1}:new int[]{3,0,0,0,0,6};}
 public Set<BlockPos> cells(BlockPos core,Direction dir){var cells=new LinkedHashSet<BlockPos>();if(kind==OilDrillKind.WELL){cells.add(core);for(var p:BlockPos.betweenClosed(core.offset(-1,1,-1),core.offset(1,9,1)))cells.add(p.immutable());for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})cells.add(core.offset(x,0,z));}else{for(var source:new int[][]{dimensions(),{0,0,-1,1,-2,4},{0,0,1,-1,-1,5}}){var d=rotate(source,dir);for(var p:BlockPos.betweenClosed(core.offset(-d[4],-d[1],-d[2]),core.offset(d[5],d[0],d[3])))cells.add(p.immutable());}}return cells;}
 @Override public BlockState getStateForPlacement(BlockPlaceContext context){var dir=context.getHorizontalDirection().getOpposite();for(var pos:cells(context.getClickedPos(),dir))if(!context.getLevel().isInWorldBounds(pos)||!context.getLevel().hasChunkAt(pos)||!pos.equals(context.getClickedPos())&&!context.getLevel().getBlockState(pos).canBeReplaced())return null;return defaultBlockState().setValue(LEGACY_META,dir.get3DDataValue()+10);}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity placer,ItemStack stack){if(level.isClientSide)return;var dir=placementFacing(state);var cells=cells(pos,dir);safely(()->{var placed=new HashSet<BlockPos>();placed.add(pos);var queue=new ArrayDeque<BlockPos>();queue.add(pos);while(!queue.isEmpty()){var parent=queue.removeFirst();for(var side:Direction.values()){var next=parent.relative(side);if(cells.contains(next)&&placed.add(next)){level.setBlock(next,defaultBlockState().setValue(LEGACY_META,side.get3DDataValue()),3);queue.add(next);}}}});if(kind==OilDrillKind.PUMPJACK)for(var port:OilDrillEntity.portPositions(pos,dir,kind))setPort(level,port,true);if(level.getBlockEntity(pos) instanceof OilDrillEntity machine){if(stack.has(net.minecraft.core.component.DataComponents.CUSTOM_NAME))machine.setCustomName(stack.getHoverName());machine.restore(stack);}}
 @Override protected net.minecraft.world.InteractionResult useWithoutItem(BlockState state,Level level,BlockPos pos,Player player,net.minecraft.world.phys.BlockHitResult hit){if(level.isClientSide)return net.minecraft.world.InteractionResult.SUCCESS;if(!player.isShiftKeyDown()){var machine=core(level,pos);if(machine!=null&&player instanceof net.minecraft.server.level.ServerPlayer server)server.openMenu(machine,buf->{buf.writeBlockPos(machine.getBlockPos());buf.writeUtf(kind.name());});}return net.minecraft.world.InteractionResult.CONSUME;}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new OilDrillEntity(pos,state):isPort(state)&&kind==OilDrillKind.PUMPJACK?new OilDrillPort(pos,state):null;}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return isCore(state)?createTickerHelper(type,OilExtractionContent.ENTITY.get(kind).get(),OilDrillEntity::tick):null;}
 private OilDrillEntity core(BlockGetter level,BlockPos pos){var core=findCore(level,pos);return core!=null&&level.getBlockEntity(core) instanceof OilDrillEntity entity?entity:null;}
 @Override public boolean onDestroyedByPlayer(BlockState state,Level level,BlockPos pos,Player player,boolean harvest,net.minecraft.world.level.material.FluidState fluid){if(!level.isClientSide&&harvest&&core(level,pos)!=null)return true;return super.onDestroyedByPlayer(state,level,pos,player,harvest,fluid);}
 @Override public void playerDestroy(Level level,Player player,BlockPos pos,BlockState state,BlockEntity original,ItemStack tool){var machine=core(level,pos);try{super.playerDestroy(level,player,pos,state,machine==null?original:machine,tool);}finally{if(machine!=null&&core(level,pos)==machine)level.removeBlock(pos,false);}}
 @Override protected List<ItemStack> getDrops(BlockState state,LootParams.Builder params){if(params.getOptionalParameter(LootContextParams.BLOCK_ENTITY) instanceof OilDrillEntity machine)return List.of(machine.dropStack());var origin=params.getOptionalParameter(LootContextParams.ORIGIN);var machine=origin==null?null:core(params.getLevel(),BlockPos.containing(origin));return machine==null?List.of():List.of(machine.dropStack());}
 @Override public ItemStack getCloneItemStack(LevelReader level,BlockPos pos,BlockState state){var machine=core(level,pos);return machine==null?new ItemStack(this):machine.dropStack();}
 @Override public void onBlockExploded(BlockState state,Level level,BlockPos pos,Explosion explosion){if(kind==OilDrillKind.PUMPJACK){super.onBlockExploded(state,level,pos,explosion);return;}var machine=core(level,pos);if(machine==null||machine.explosionHandled)return;machine.explosionHandled=true;var core=machine.getBlockPos();boolean fuel=machine.tanks[0].getFill()>0||machine.tanks[1].getFill()>0;machine.tanks[0].setFill(0);machine.tanks[1].setFill(0);level.removeBlock(pos,false);if(fuel){new com.hbm.explosion.vanillant.ExplosionVNT(level,core.getX()+.5,core.getY()+.5,core.getZ()+.5,15).setBlockAllocator(new com.hbm.explosion.vanillant.standard.BlockAllocatorStandard(24)).setBlockProcessor(new com.hbm.explosion.vanillant.standard.BlockProcessorStandard().setNoDrop()).setEntityProcessor(new com.hbm.explosion.vanillant.standard.EntityProcessorStandard()).setPlayerProcessor(new com.hbm.explosion.vanillant.standard.PlayerProcessorStandard()).explode();com.hbm.bomb.conventional.LargeConventionalEffects.small(level,core.getX()+.5,core.getY()+.5,core.getZ()+.5);}}
}
